package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NamibiaFractionOrderingTest {
 @Test public void bothMenusAndDirectionsUsePublicOriginalCards(){String pack="na-nied-primary-2024-v1";Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"NA");GlobalCurriculum.choosePack(p,pack);for(String id:List.of("fractionOrder","likeFractionOrder")){assertTrue(GlobalCurriculum.pack(p).inGrade(id,6));Generator g=new Generator(new Random(274));List<String>recent=new ArrayList<>();boolean up=false,down=false,different=false,largeDen=false;for(int i=0;i<100;i++){Question q=g.next(id,recent,false,GlobalCurriculum.limits(pack,id,6));assertFalse(recent.contains(q.signature()));recent.add(q.signature());List<String>original=FractionOrdering.givens(q);boolean reverse=q.prompt.startsWith("큰");up|=!reverse;down|=reverse;Set<String>den=new HashSet<>();for(String v:original){assertTrue(Expression.number(v).compareTo(Rational.ZERO)>0&&Expression.number(v).compareTo(Rational.ONE)<=0);int b=Integer.parseInt(v.split("/")[1]);assertTrue(b>=2&&b<=100);largeDen|=b>12;den.add(v.split("/")[1]);}if(id.equals("likeFractionOrder"))assertEquals(1,den.size());else different|=den.size()>1;List<String>sorted=new ArrayList<>(original);sorted.sort((a,b)->Expression.number(a).compareTo(Expression.number(b))*(reverse?-1:1));q.answers=new String[]{"poison"};q.expression="poison";assertTrue(new Checker().check(q,List.of(),sorted).correct());Collections.swap(sorted,0,1);assertFalse(new Checker().check(q,List.of(),sorted).correct());HelpPlan h=HelpPlan.forQuestion(q);assertEquals(3,h.size());assertFalse(h.canTransfer());assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));}assertTrue(up&&down&&largeDen);if(id.equals("fractionOrder"))assertTrue(different);}}
 @Test public void hundredDenominatorOriginalCardsStayUnreduced(){Question q=new Question("likeFractionOrder","큰 분수부터 고르세요.\n100/100 · 1/100 · 99/100","poison","poison");assertTrue(new Checker().check(q,List.of(),List.of("100/100","99/100","1/100")).correct());assertFalse(new Checker().check(q,List.of(),List.of("1","99/100","1/100")).correct());assertEquals(100,Arrays.stream(GlobalCurriculum.limits("na-nied-primary-2024-v1","fractionOrder",6).fractionDenominators()).max().orElseThrow());}
}
